// Aggregate all ingested finance data from disk and return it as a single
// JSON response the PWA can render. Pure read-only — no mutations.
//
// Reads:
//   /data/finance-events/bank/<institution-or-filename>/<txid>.json
//   /data/finance-events/gmail/<id>.json
//   /data/finance-events/reconciled/_reconcile_state.json (for status lookups)
//   /data/chatin/_reconcile_state.json (alt location after the path fix)
//
// Output shape: { transactions: [...], gmail_events: [...], counts: {...} }
// Query params (passed via $input.first().json.query):
//   ?limit=500         (default 500, max 5000)
//   ?offset=0
//   ?institution=chase (filter)
//   ?status=verified   (verified | unconfirmed | unexplained | all)
//   ?since=2026-01-01  (only transactions on/after)

const fs = require('fs');
const path = require('path');

const BANK_ROOT = '/data/finance-events/bank';
const GMAIL_DIR = '/data/finance-events/gmail';
const RECONCILED_DIR = '/data/finance-events/reconciled';
const STATE_FILES = [
  '/data/chatin/_reconcile_state.json',
  '/data/finance-events/_reconcile_state.json'
];

const input = $input.first().json || {};
const q = (input.query && typeof input.query === 'object') ? input.query : (input.body && input.body.query) || {};
const limit = Math.min(parseInt(q.limit || '500', 10) || 500, 5000);
const offset = parseInt(q.offset || '0', 10) || 0;
const institutionFilter = (q.institution || '').toLowerCase();
const statusFilter = (q.status || 'all').toLowerCase();
const sinceFilter = q.since ? new Date(q.since).getTime() : 0;

function walk(dir, out, depth) {
  if (depth > 4) return;
  let entries;
  try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch (_) { return; }
  for (const e of entries) {
    if (e.name.startsWith('_')) continue;
    const full = path.join(dir, e.name);
    if (e.isDirectory()) walk(full, out, depth + 1);
    else if (e.name.endsWith('.json')) out.push(full);
  }
}

// Load reconcile state for status lookups.
let reconcileState = { reconciled_ids: {} };
for (const sf of STATE_FILES) {
  try {
    reconcileState = JSON.parse(fs.readFileSync(sf, 'utf8'));
    break;
  } catch (_) {}
}

function lookupStatus(key) {
  const r = reconcileState.reconciled_ids && reconcileState.reconciled_ids[key];
  return (r && r.status) || 'unknown';
}

// Load bank transactions.
const bankFiles = [];
walk(BANK_ROOT, bankFiles, 0);

const bankTransactions = [];
for (const f of bankFiles) {
  let rec;
  try { rec = JSON.parse(fs.readFileSync(f, 'utf8')); } catch (_) { continue; }
  const t = rec.transaction || {};
  const inst = (rec.institution || '').toLowerCase();
  if (institutionFilter && inst.indexOf(institutionFilter) === -1) continue;
  const posted = t.posted || rec.captured_at;
  const postedMs = posted ? new Date(posted).getTime() : 0;
  if (sinceFilter && postedMs < sinceFilter) continue;
  const statusKey = inst + ':' + (t.fitid || (posted + '-' + t.amount + '-' + (t.name || '')));
  const status = lookupStatus(statusKey);
  if (statusFilter !== 'all' && status !== statusFilter) continue;
  bankTransactions.push({
    id: path.basename(f, '.json'),
    source: 'bank',
    institution: rec.institution,
    source_file: rec.source_file,
    posted: t.posted,
    amount: t.amount,
    name: t.name,
    memo: t.memo,
    type: t.type,
    fitid: t.fitid,
    status,
    captured_at: rec.captured_at
  });
}

// Load Gmail finance events.
let gmailFiles = [];
try {
  gmailFiles = fs.readdirSync(GMAIL_DIR).filter(f => f.endsWith('.json')).map(f => path.join(GMAIL_DIR, f));
} catch (_) {}

const gmailEvents = [];
for (const f of gmailFiles) {
  let rec;
  try { rec = JSON.parse(fs.readFileSync(f, 'utf8')); } catch (_) { continue; }
  const internalDate = rec.internal_date || rec.captured_at;
  if (sinceFilter && internalDate && new Date(internalDate).getTime() < sinceFilter) continue;
  const status = lookupStatus(rec.gmail_id);
  if (statusFilter !== 'all' && status !== statusFilter && status !== 'unknown') continue;
  gmailEvents.push({
    id: rec.gmail_id || path.basename(f, '.json'),
    source: 'gmail',
    from: rec.from,
    subject: rec.subject,
    snippet: rec.snippet,
    internal_date: internalDate,
    amount: rec.extracted && rec.extracted.amount,
    direction: rec.extracted && rec.extracted.direction,
    status,
    captured_at: rec.captured_at
  });
}

// Sort: newest first.
bankTransactions.sort((a, b) => (b.posted || '').localeCompare(a.posted || ''));
gmailEvents.sort((a, b) => (b.internal_date || '').localeCompare(a.internal_date || ''));

const pagedBank = bankTransactions.slice(offset, offset + limit);
const pagedGmail = gmailEvents.slice(0, Math.min(200, gmailEvents.length));

// Quick stats for the PWA's summary header.
const statusCounts = { verified: 0, unconfirmed: 0, unexplained: 0, unknown: 0 };
for (const t of bankTransactions) statusCounts[t.status] = (statusCounts[t.status] || 0) + 1;

const institutions = Array.from(new Set(bankTransactions.map(t => t.institution).filter(Boolean))).sort();

return [{
  json: {
    served_at: new Date().toISOString(),
    counts: {
      total_bank: bankTransactions.length,
      total_gmail: gmailEvents.length,
      status_counts: statusCounts,
      institutions
    },
    transactions: pagedBank,
    gmail_events: pagedGmail,
    page: { limit, offset, has_more: offset + limit < bankTransactions.length }
  }
}];
